"""Write a committed manifest for MCMC chain archives that are kept outside Git.

    python scripts/make_chain_manifest.py results/m3/mcmc --code-commit <sha> \
        --note "generated by scripts/m3_mcmc.py"

For every *.npz below the directory it records the path (relative to the
repository), size, SHA-256, and the run metadata stored inside the archive
(`meta` JSON), and writes DIR/MANIFEST.json and DIR/MANIFEST.sha256 (the latter
in `shasum -a 256 -c` format, paths relative to the repository root).
The archives themselves are never modified.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import pathlib
import time

import numpy as np

ROOT = pathlib.Path(__file__).resolve().parents[1]


def sha256(path: pathlib.Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("directory")
    ap.add_argument("--code-commit", required=True)
    ap.add_argument("--note", default="")
    args = ap.parse_args()
    base = (ROOT / args.directory).resolve()
    entries = []
    for f in sorted(base.rglob("*.npz")):
        rel = f.relative_to(ROOT).as_posix()
        meta = None
        try:
            with np.load(f) as d:
                if "meta" in d.files:
                    meta = json.loads(str(d["meta"]))
                    meta.pop("config", None)  # identical for all chains; recorded once below
                shapes = {k: list(d[k].shape) for k in d.files if k != "meta"}
        except Exception as exc:  # never fail on an unreadable archive; record it
            shapes = {"error": str(exc)}
        entries.append({"path": rel, "bytes": f.stat().st_size, "sha256": sha256(f),
                        "arrays": shapes, "meta": meta})
    manifest = {
        "description": "MCMC chain archives kept outside Git (see .gitignore). Verify with: "
                       f"shasum -a 256 -c {(base / 'MANIFEST.sha256').relative_to(ROOT).as_posix()} "
                       "(run from the repository root).",
        "storage_location": "local working copy of the repository at the listed paths; not pushed to GitHub",
        "code_commit": args.code_commit,
        "note": args.note,
        "created": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "n_files": len(entries),
        "total_bytes": int(sum(e["bytes"] for e in entries)),
        "files": entries,
    }
    (base / "MANIFEST.json").write_text(json.dumps(manifest, indent=1) + "\n")
    (base / "MANIFEST.sha256").write_text("".join(f"{e['sha256']}  {e['path']}\n" for e in entries))
    print(f"{len(entries)} archives, {manifest['total_bytes'] / 1e6:.1f} MB -> "
          f"{(base / 'MANIFEST.json').relative_to(ROOT)}")


if __name__ == "__main__":
    main()
